      ]
    }
  ],
  "sem_lancamento_contabil_efetuado": [
    {
      "item": "Brindes a clientes - NF-e 4410 (Brindes Prime, 12/02/2026, CFOP 1949), R$ 48.000,00 em 4.2.02",
